"use client";

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { getProducts } from "@/services/products";
import { getCustomers } from "@/services/customers";
import { getSuppliers } from "@/services/suppliers";

interface OrderItem {
  productId: string;
  name: string;
  quantity: number;
  price: number;
}

export default function OrderForm({
  onSubmit,
}: {
  onSubmit: (data: any) => void;
}) {
  const [type, setType] = useState<"SALE" | "PURCHASE">("SALE");
  const [entityId, setEntityId] = useState("");
  const [items, setItems] = useState<OrderItem[]>([]);
  
  const [selectedProductId, setSelectedProductId] = useState("");
  const [quantity, setQuantity] = useState(1);
  const [price, setPrice] = useState(0);

  const { data: products } = useQuery({ queryKey: ["products"], queryFn: getProducts });
  const { data: customers } = useQuery({ queryKey: ["customers"], queryFn: getCustomers, enabled: type === "SALE" });
  const { data: suppliers } = useQuery({ queryKey: ["suppliers"], queryFn: getSuppliers, enabled: type === "PURCHASE" });

  const addItem = () => {
    const product = products?.find((p: any) => p.id === selectedProductId);
    if (!product) return;

    setItems([...items, {
      productId: product.id,
      name: product.name,
      quantity,
      price: price || product.price,
    }]);

    setSelectedProductId("");
    setQuantity(1);
    setPrice(0);
  };

  const removeItem = (index: number) => {
    setItems(items.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (items.length === 0 || !entityId) return;

    onSubmit({
      type,
      customerId: type === "SALE" ? entityId : undefined,
      supplierId: type === "PURCHASE" ? entityId : undefined,
      items: items.map(item => ({
        productId: item.productId,
        quantity: item.quantity,
        price: item.price,
      })),
      status: "PENDING",
    });
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6 max-w-2xl bg-white p-6 rounded-xl shadow-sm border">
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Order Type</label>
          <select 
            className="w-full border rounded-lg p-2"
            value={type}
            onChange={(e) => {
              setType(e.target.value as any);
              setEntityId("");
            }}
          >
            <option value="SALE">Sale</option>
            <option value="PURCHASE">Purchase</option>
          </select>
        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">
            {type === "SALE" ? "Customer" : "Supplier"}
          </label>
          <select 
            className="w-full border rounded-lg p-2"
            value={entityId}
            onChange={(e) => setEntityId(e.target.value)}
            required
          >
            <option value="">Select {type === "SALE" ? "Customer" : "Supplier"}</option>
            {(type === "SALE" ? customers : suppliers)?.map((e: any) => (
              <option key={e.id} value={e.id}>{e.name}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="border-t pt-4">
        <h3 className="font-medium mb-3">Add Items</h3>
        <div className="grid grid-cols-4 gap-3 items-end">
          <div className="col-span-1">
            <select 
              className="w-full border rounded-lg p-2 text-sm"
              value={selectedProductId}
              onChange={(e) => {
                setSelectedProductId(e.target.value);
                const p = products?.find((prod: any) => prod.id === e.target.value);
                if (p) setPrice(p.price);
              }}
            >
              <option value="">Product...</option>
              {products?.map((p: any) => (
                <option key={p.id} value={p.id}>{p.name}</option>
              ))}
            </select>
          </div>
          <div>
            <input 
              type="number"
              placeholder="Qty"
              min="1"
              className="w-full border rounded-lg p-2 text-sm"
              value={quantity}
              onChange={(e) => setQuantity(Number(e.target.value))}
            />
          </div>
          <div>
            <input 
              type="number"
              placeholder="Price"
              min="0"
              step="0.01"
              className="w-full border rounded-lg p-2 text-sm"
              value={price}
              onChange={(e) => setPrice(Number(e.target.value))}
            />
          </div>
          <button 
            type="button"
            onClick={addItem}
            className="bg-gray-100 hover:bg-gray-200 p-2 rounded-lg text-sm font-medium"
          >
            Add
          </button>
        </div>
      </div>

      <div className="mt-4">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-gray-50 border-b">
              <th className="p-2 text-left">Item</th>
              <th className="p-2 text-right">Qty</th>
              <th className="p-2 text-right">Price</th>
              <th className="p-2 text-right">Total</th>
              <th className="p-2"></th>
            </tr>
          </thead>
          <tbody>
            {items.map((item, i) => (
              <tr key={i} className="border-b">
                <td className="p-2">{item.name}</td>
                <td className="p-2 text-right">{item.quantity}</td>
                <td className="p-2 text-right">₹{item.price}</td>
                <td className="p-2 text-right">₹{item.quantity * item.price}</td>
                <td className="p-2 text-right">
                  <button onClick={() => removeItem(i)} className="text-red-500 hover:text-red-700">✕</button>
                </td>
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr className="font-bold">
              <td colSpan={3} className="p-2 text-right">Grand Total:</td>
              <td className="p-2 text-right">₹{items.reduce((acc, item) => acc + (item.quantity * item.price), 0)}</td>
              <td></td>
            </tr>
          </tfoot>
        </table>
      </div>

      <button 
        type="submit"
        disabled={items.length === 0 || !entityId}
        className="w-full bg-teal-600 text-white p-3 rounded-lg font-bold disabled:bg-gray-300 transition-colors"
      >
        Submit Order
      </button>
    </form>
  );
}
